const here = position();
if (inventory_count('cobblestone') < 4) {
  const took = await take_from_depot('cobblestone');
  if (!took.ok) {
    return { done: false, detail: took.detail };
  }
}
for (let i = 0; i < 4; i++) {
  const put = await place('cobblestone', here.x + i, here.y, here.z);
  if (!put.ok) {
    return { done: false, detail: put.detail };
  }
}
return { done: true, detail: 'laid four cobblestone' };
